    12	export const GBNF = (input: string | GBNFRule, initialString: ValidInput = ''): ParseState => {
    13	  const grammar = typeof input === 'string' ? input : input.toString();
    14	  const { rules, symbolIds, } = new RulesBuilder(grammar);
    15	  if (rules.length === 0) {
    16	    throw new GrammarParseError(grammar, 0, 'No rules were found');
    17	  }
    18	  if (symbolIds.get('root') === undefined) {
    19	    throw new GrammarParseError(grammar, 0, `Grammar does not contain a root symbol. Available symbols are: ${JSON.stringify(symbolIds.keys())}`);
    20	  }
    21	  const rootId = symbolIds.get('root');
    22	
    23	  const stackedRules: UnresolvedRule[][][] = rules.map(buildRuleStack);
    24	  const graph = new Graph(grammar, stackedRules, rootId);
    25	  return new ParseState(graph, graph.add(initialString));
    26	};
